CREATE OR REPLACE VIEW `implode_img` AS select `p`.`company_id` AS `company_id`,`pi`.`product_id` AS `product_id`,group_concat(coalesce(`i`.`path`,'') separator ',') AS `imploded` from ((`product_images` `pi` join `products` `p` on(`p`.`pro_id` = `pi`.`product_id`)) left join `images` `i` on(`i`.`uuid` = `pi`.`image_id`)) where `pi`.`deleted_at` is null group by `pi`.`product_id`,`p`.`company_id`;
